/* The TAP ape (0.9.2): SHIFT + B6's TAP takeover, mockups/fizz-tap-ape.html drawn for FIZZ (its sheet,
 * mockups/png/fizz-tap-ape-sheet.png). The owner's breakdancing gorilla, traced from their reference into twelve poses
 * (ape_poses.h, generated by tools/gen_ape_poses.py from mockups/fizz-tap-ape-data.js), on the floor at the right of
 * its boombox; "TAP", the BPM (44 px, top left) and the tap dots kept from the old screen.
 *   - The first tap of a count: pose 1 (point-and-squat), the ape bouncing in from the right (not when the screen was
 *     still up: then it hops as any tap does). Taps 2..: poses 2..11 round (step, side lean, knuckle crouch, side
 *     kick, handstand, one-arm air freeze, spin, lying freeze, headstand, back freeze); 2 s after the last tap the
 *     finale, pose 12 (kneel, fist up), the dots cleared; the screen closes at 2.8 s (ctl.h QD_TAP_TK_MS, faded).
 *   - Each tap: the jump to the pose, a 9 px hop and a stretch, a cream flash over the lines (120 ms), the old pose's
 *     ghost fading, streaks either side, sparkles bursting, the boombox pumping and its sound arcs.
 *   - Between taps (a tempo: 2 taps and more) the whole drawing grooves on the beat, one transform a frame: standing
 *     poses bob, freezes rock, the spin swings, the headstand turns as a paper doll (its width the cosine, half a turn
 *     a beat, never under 25 %).
 *   - An external clock: the lying freeze on the boombox, dimmed to 45 % and breathing, a clock beside the grey BPM.
 *   - 180 BPM and up: every tap the headstand's flurry: turning twice as fast, rainbow rings (the tracks' colours)
 *     round its legs, a sparkle shower, the boombox shaking.
 * Each colour one path (quadratics through the midpoints), its line alone (P2.6d, the owner: no glow on the poses,
 * the boombox or the other neon lines; the moonwalk without its trails). Built through ui_turn.c (it includes this file). */
#include "ape_poses.h"

#define AP_S 0.85f                       /* the scene's scale (the poses' px) */
#define AP_BX 6.f                        /* the boombox's left edge */
#define AP_BW 80.f                       /* .. its size (the poses' px) */
#define AP_BH 56.f
#define AP_FY 204.f                      /* the floor */
#define AP_HOP 0.24f                     /* a tap's hop (s) */
#define AP_TADA 2.0f                     /* the finale after the last tap (s) */
#define AP_CLEAR0 1.6f                   /* the dots start clearing */
#define AP_ENTER 0.32f                   /* the first tap's bounce in */
#define AP_FINALE 11                     /* kneel, fist up */
#define AP_FLURRY 9                      /* the headstand */
#define AP_TAU 6.2831853f

enum { AP_TAP, AP_ENTERS, AP_TADAS };
enum { GR_BOB, GR_ROCK, GR_SPIN, GR_FLIP };
static const uint8_t AP_GROOVE[APE_NPOSE] = {GR_BOB, GR_BOB, GR_BOB, GR_BOB, GR_BOB, GR_ROCK, GR_ROCK, GR_SPIN, GR_ROCK,
                                             GR_FLIP, GR_ROCK, GR_BOB};
/* the reference's neon: cyan, flowers, shirt, gold, fur (the drawing order); the boombox; the flash */
static const qd_rgb AP_COL[APE_NCOL] = {0x3fe4f2u, 0x4fe08cu, 0xff9440u, 0xffe066u, 0xff62d2u};
#define AP_CYAN 0x3fe4f2u
#define AP_LEAF 0x4fe08cu
#define AP_SHIRT 0xff9440u
#define AP_GOLD 0xffe066u
#define AP_FUR 0xff62d2u
#define AP_BOX 0xa2a2aeu
#define AP_CREAM 0xfff1d0u
static const float AP_GW[3] = {3.4f, 2.f, 1.f}, AP_GA[3] = {0.14f, 0.3f, 1.f};   /* the glow: width, alpha */
#define AP_G0 2                          /* P2.6d (the owner): the first of those strokes drawn: the line alone (no glow) for
                                          * the poses, the boombox and every neon line; the flurry's rings keep theirs */

static float ap_dim = 1.f;               /* (the external clock: every colour at 45 %) */
static qd_rgb ap_c(qd_rgb c)
{
    if (ap_dim >= 1.f)
        return c;
    return (qd_rgb)((uint32_t)((float)((c >> 16) & 255u) * ap_dim) << 16 | (uint32_t)((float)((c >> 8) & 255u) * ap_dim) << 8 |
                    (uint32_t)((float)(c & 255u) * ap_dim));
}
static float ap_clamp(float x) { return x < 0.f ? 0.f : x > 1.f ? 1.f : x; }
static float ap_ease(float x) { x = ap_clamp(x); return x * x * (3.f - 2.f * x); }
static float ap_easeout(float x) { x = 1.f - ap_clamp(x); return 1.f - x * x * x; }
static float ap_hash(float n)                           /* 0..1 from n: P2.4, an integer hash of its bits (was a sine
                                                         * in double: no double on the unit) */
{
    union {
        float f;
        uint32_t u;
    } b;
    uint32_t h;
    b.f = n;
    h = b.u * 0x9E3779B1u;
    h ^= h >> 15;
    h *= 0x85EBCA77u;
    h ^= h >> 13;
    return (float)(h >> 8) * (1.f / 16777216.f);
}

int ui_ape_pose(int n, int bpm)
{
    if (n <= 1)
        return 0;
    if (bpm >= 180)
        return AP_FLURRY;
    return 1 + (n - 2) % 10;
}

/* ---------------------------------------------------------------- neon: three strokes */
static void ap_glow_path(qd_rgb col, float lw)    /* the path made: stroked three times, then ended */
{
    int g;
    for (g = AP_G0; g < 3; g++) {
        qd_save();
        qd_alpha(qd_get_alpha() * AP_GA[g]);
        qd_path_stroke_keep(ap_c(col), lw * AP_GW[g]);
        qd_restore();
    }
    qd_path_begin();
}
static void ap_line(const float *xy, int n, qd_rgb col, float lw)
{
    int i;
    qd_path_begin();
    qd_move_to(xy[0], xy[1]);
    for (i = 1; i < n; i++)
        qd_line_to(xy[2 * i], xy[2 * i + 1]);
    ap_glow_path(col, lw);
}
static void ap_line2(float x0, float y0, float x1, float y1, qd_rgb col, float lw)
{
    const float p[4] = {x0, y0, x1, y1};
    ap_line(p, 2, col, lw);
}
static void ap_circ(float x, float y, float r, qd_rgb col, float lw)
{
    qd_path_begin();
    qd_path_arc(x, y, r > 0.1f ? r : 0.1f, 0.f, AP_TAU);
    qd_path_close();
    ap_glow_path(col, lw);
}
static void ap_arc(float x, float y, float r, float a0, float a1, qd_rgb col, float lw)
{
    qd_path_begin();
    qd_move_to(x + cosf(a0) * r, y + sinf(a0) * r);
    qd_path_arc(x, y, r, a0, a1);
    ap_glow_path(col, lw);
}
static void ap_rect(float x, float y, float w, float h, float r, qd_rgb col, float lw, qd_rgb fill)
{
    int g;
    if (fill != QD_NONE)
        qd_rrect(x, y, w, h, r, QD_NONE, 0.f, fill);
    for (g = AP_G0; g < 3; g++) {
        qd_save();
        qd_alpha(qd_get_alpha() * AP_GA[g]);
        qd_rrect(x, y, w, h, r, ap_c(col), lw * AP_GW[g], QD_NONE);
        qd_restore();
    }
}
static void ap_sparkle(float x, float y, float r, qd_rgb col)
{
    ap_line2(x - r, y, x + r, y, col, 1.3f);
    ap_line2(x, y - r, x, y + r, col, 1.3f);
}

/* ---------------------------------------------------------------- the poses */
static int16_t ap_i16(const uint8_t *b) { return (int16_t)(b[0] | b[1] << 8); }
#ifndef QD_DEVICE
/* colour c of pose k into the path (the pose's units: half px, y up negative): its smooth lines as quadratics through
 * the midpoints, its straight chains as lines */
static void ap_path_part(int k, int c, int p0, int p1)   /* (its polylines p0 .. p1 - 1 only: the others read past) */
{
    const uint8_t *b = APE_BYTES + APE_POSES[k].off[c];
    int n = APE_POSES[k].n[c] < p1 ? APE_POSES[k].n[c] : p1, px = 0, py = 0, first = 1, p = 0;
    for (; p < n; p++) {
        const int h = *b++, np = (h & 63) + 1, straight = h & 0x80;
        int x, y, i;
        float pts[2 * 65];
        if (h & 0x40) {
            x = px, y = py;
        } else if (first) {
            x = ap_i16(b), y = ap_i16(b + 2), b += 4;
        } else if ((int8_t)b[0] == -128) {
            x = ap_i16(b + 1), y = ap_i16(b + 3), b += 5;
        } else {
            x = px + (int8_t)b[0], y = py + (int8_t)b[1], b += 2;
        }
        first = 0;
        pts[0] = (float)x, pts[1] = (float)y;
        for (i = 1; i < np; i++) {
            x += (int8_t)b[0], y += (int8_t)b[1], b += 2;
            pts[2 * i] = (float)x, pts[2 * i + 1] = (float)y;
        }
        px = x, py = y;
        if (p < p0)
            continue;
        qd_move_to(pts[0], pts[1]);
        if (straight || np == 2) {
            for (i = 1; i < np; i++)
                qd_line_to(pts[2 * i], pts[2 * i + 1]);
        } else {
            for (i = 1; i < np - 1; i++)
                qd_quad_to(pts[2 * i], pts[2 * i + 1], (pts[2 * i] + pts[2 * i + 2]) * 0.5f,
                           (pts[2 * i + 1] + pts[2 * i + 3]) * 0.5f);
            qd_line_to(pts[2 * (np - 1)], pts[2 * (np - 1) + 1]);
        }
    }
}
static void ap_path(int k, int c) { ap_path_part(k, c, 0, 255); }
#endif

typedef struct { float x0, x1, y0, y1, cx, cy; } ap_box_t;
static float ap_posex(int k) { return k == 8 ? AP_BX : 236.f - AP_S * (float)APE_POSES[k].ext[2]; }
static ap_box_t ap_posebox(int k, float dx)
{
    const int16_t *e = APE_POSES[k].ext;
    const float x = ap_posex(k) + dx;
    ap_box_t b;
    b.x0 = x + AP_S * (float)e[0], b.x1 = x + AP_S * (float)e[2];
    b.y0 = AP_FY - AP_S * (float)e[3], b.y1 = AP_FY - AP_S * (float)e[1];
    b.cx = x + AP_S * (float)(e[0] + e[2]) * 0.5f, b.cy = AP_FY - AP_S * (float)(e[1] + e[3]) * 0.5f;
    return b;
}
#ifdef QD_DEVICE
/* P2.1 (the owner: "you should be able to procedurally draw the ape's poses for pretty cheap"): at the device's sizes no
 * layers and no cache (they were 384 KB): each frame draws the pose it shows from its lines, made cheap: straight
 * segments through the traced points, a point kept only when it is AP_LITE units (half px) or more from the last one
 * kept (a polyline's ends always), each line stroked twice (a soft glow, the line) instead of three times; the snap's
 * flash the same lines once in cream. P2.1b: each line by itself (the arena holds one line's outline). The host keeps the cached, smoothed, three-stroke drawing */
#define AP_LITE 7
/* P2.1b: each line drawn by itself (its glow, then itself; the device's arena holds one line's outline, not a colour's);
 * a line out of the strip (its glow's width round it): left out */
typedef struct {
    qd_rgb col;
    float lw, glow;                     /* (glow: its glow's width, 0 none) */
} ap_ink_t;
static void ap_path_lite(int k, int c, const ap_ink_t *ink)
{
    const uint8_t *b = APE_BYTES + APE_POSES[k].off[c];
    int n = APE_POSES[k].n[c], px = 0, py = 0, first = 1, p;
    for (p = 0; p < n; p++) {
        const int h = *b++, np = (h & 63) + 1;
        int x, y, i, lx, ly, nk = 0, x0, y0, x1, y1;
        int16_t kx[64], ky[64];
        if (h & 0x40) {
            x = px, y = py;
        } else if (first) {
            x = ap_i16(b), y = ap_i16(b + 2), b += 4;
        } else if ((int8_t)b[0] == -128) {
            x = ap_i16(b + 1), y = ap_i16(b + 3), b += 5;
        } else {
            x = px + (int8_t)b[0], y = py + (int8_t)b[1], b += 2;
        }
        first = 0;
        kx[nk] = (int16_t)x, ky[nk++] = (int16_t)y;
        x0 = x1 = x, y0 = y1 = y;
        lx = x, ly = y;
        for (i = 1; i < np; i++) {
            x += (int8_t)b[0], y += (int8_t)b[1], b += 2;
            if (i == np - 1 || (x - lx) * (x - lx) + (y - ly) * (y - ly) >= AP_LITE * AP_LITE) {
                kx[nk] = (int16_t)x, ky[nk++] = (int16_t)y;
                x0 = x < x0 ? x : x0, x1 = x > x1 ? x : x1, y0 = y < y0 ? y : y0, y1 = y > y1 ? y : y1;
                lx = x, ly = y;
            }
        }
        px = x, py = y;
        if (!qd_box_visible((float)x0, (float)y0, (float)(x1 - x0), (float)(y1 - y0), ink->glow > ink->lw ? ink->glow
                                                                                                      : ink->lw))
            continue;
        qd_path_begin();
        qd_move_to((float)kx[0], (float)ky[0]);
        for (i = 1; i < nk; i++)
            qd_line_to((float)kx[i], (float)ky[i]);
        if (ink->glow > 0.f) {
            qd_save();
            qd_alpha(qd_get_alpha() * 0.22f);
            qd_path_stroke_keep(ink->col, ink->glow);
            qd_restore();
        }
        qd_path_stroke(ink->col, ink->lw);
    }
}
typedef struct { float dx, lift, sx, sy, rot, alpha, flash; int mid; } ap_pose_o;
static void ap_pose(int k, const ap_pose_o *o)
{
    const ap_box_t b = ap_posebox(k, o->dx);
    const float ax = b.cx, ay = o->mid ? b.cy : AP_FY, lw = 1.55f * 2.f / AP_S;
    int c;
    qd_save();
    qd_alpha(qd_get_alpha() * o->alpha);
    qd_translate(ax, ay - o->lift);
    if (o->rot != 0.f)
        qd_rotate(o->rot);
    qd_scale(o->sx, o->sy);
    qd_translate(-ax, -ay);
    qd_translate(ap_posex(k) + o->dx, AP_FY);
    qd_scale(AP_S * 0.5f, AP_S * 0.5f);
    for (c = 0; c < APE_NCOL; c++) {
        const ap_ink_t ink = {ap_c(AP_COL[c]), lw, 0.f};   /* (P2.6d: no glow) */
        if (APE_POSES[k].n[c])
            ap_path_lite(k, c, &ink);
    }
    if (o->flash > 0.f) {
        const ap_ink_t ink = {AP_CREAM, lw * 1.1f, 0.f};
        qd_alpha(qd_get_alpha() * o->flash * 0.7f);
        for (c = 0; c < APE_NCOL; c++)
            ap_path_lite(k, c, &ink);
    }
    qd_restore();
}
static int ap_keep[2] = {-1, -1};
static int ap_prepare(int k) { (void)k; return 0; }
void ui_ape_forget(void) {}
void ui_ape_prewarm(int ext) { (void)ext; }
#else
/* The poses cached (0.9.2.1: the site draws FIZZ inside the browser's audio thread; the unit needs it cheap too). A pose
 * is drawn once, into a layer at full resolution (its glow and its lines, a colour at a time as on screen), and a half
 * resolution layer of its lines in cream for the tap's flash; each frame places them with the groove's transform. Three
 * poses are kept (the one shown, the one it left, being the ghost, and the one coming: the next of the loop, or the
 * finale near the end of a count, or the first pose while SHIFT is held, ui_ape_prewarm); the coming one is built a
 * colour a frame, so no frame pays for a whole pose (a pose wanted at once and not ready is finished there and then). */
#define AP_NC 3                          /* the poses cached */
#define AP_PART 12                       /* a pose's build: its colours, up to this many polylines a part, then the flash */
typedef struct {
    int k;                               /* the pose (-1 none) */
    int done;                            /* its polylines drawn (every colour's in turn, then again for the flash; twice
                                          * its count: ready) */
    float x, y, w, h;                    /* where its layer goes (screen px, the pose unmoved) */
    uint32_t used;
} ap_cache_t;
static ap_cache_t ap_cache[AP_NC] = {{-1, 0, 0.f, 0.f, 0.f, 0.f, 0u}, {-1, 0, 0.f, 0.f, 0.f, 0.f, 0u},
                                     {-1, 0, 0.f, 0.f, 0.f, 0.f, 0u}};
static uint32_t ap_use;
static int ap_keep[2] = {-1, -1};        /* the poses not to evict now (shown, ghost) */

static void ap_strokes(int k, int g0, int g1)
{
    const float lw = 1.55f * 2.f / AP_S;
    int c, g;
    for (c = 0; c < APE_NCOL; c++) {
        if (!APE_POSES[k].n[c])
            continue;
        qd_path_begin();
        ap_path(k, c);
        for (g = g0; g <= g1; g++) {
            qd_save();
            qd_alpha(qd_get_alpha() * AP_GA[g]);
            qd_path_stroke_keep(ap_c(AP_COL[c]), lw * AP_GW[g]);
            qd_restore();
        }
        qd_path_begin();
    }
}
/* the cache entry holding pose k (made, evicting the oldest not kept, if none); -1 none */
static int ap_entry(int k)
{
    const float m = 4.f;
    ap_cache_t *e;
    int i, best = -1;
    for (i = 0; i < AP_NC; i++)
        if (ap_cache[i].k == k)
            return i;
    for (i = 0; i < AP_NC; i++)
        if ((ap_cache[i].k < 0 || (ap_cache[i].k != ap_keep[0] && ap_cache[i].k != ap_keep[1])) &&
            (best < 0 || ap_cache[i].k < 0 || (ap_cache[best].k >= 0 && ap_cache[i].used < ap_cache[best].used)))
            best = i;
    if (best < 0)
        return -1;
    e = &ap_cache[best];
    {
        const ap_box_t b = ap_posebox(k, 0.f);
        e->k = k, e->done = 0, e->used = ++ap_use;
        e->x = floorf(b.x0 - m), e->y = floorf(b.y0 - m);   /* (whole pixels: the lines stay crisp, unmoved) */
        e->w = ceilf(b.x1 + m) - e->x, e->h = ceilf(b.y1 + m) - e->y;
    }
    return best;
}
static int ap_total(int k)                              /* pose k's polylines */
{
    int c, n = 0;
    for (c = 0; c < APE_NCOL; c++)
        n += APE_POSES[k].n[c];
    return n;
}
#define AP_READY(e) ((e)->done >= 2 * ap_total((e)->k))
/* one part of entry i's build: up to AP_PART polylines of a colour (their glow, their line) into the pose's layer, the
 * colours in the drawing order; then the same in cream (twice as many a part: one stroke) into the flash's layer */
static int ap_build_chunk(int i)
{
    ap_cache_t *e = &ap_cache[i];
    const int k = e->k, tot = k >= 0 ? ap_total(k) : 0, flash = e->done >= tot;
    const float lw = 1.55f * 2.f / AP_S;
    int g, c = 0, p0 = flash ? e->done - tot : e->done, p1, ok;
    if (k < 0 || e->done >= 2 * tot)
        return 0;
    while (p0 >= APE_POSES[k].n[c])                     /* (the colour and its polyline the part starts at) */
        p0 -= APE_POSES[k].n[c], c++;
    p1 = p0 + (flash ? 2 * AP_PART : AP_PART);
    p1 = p1 < APE_POSES[k].n[c] ? p1 : APE_POSES[k].n[c];
    if (!flash)
        ok = e->done ? qd_layer_resume(2 * i) : qd_layer_begin(2 * i, (int)e->w, (int)e->h);
    else
        ok = e->done > tot ? qd_layer_resume(2 * i + 1)
                           : qd_layer_begin(2 * i + 1, (int)(e->w * 0.5f + 0.5f), (int)(e->h * 0.5f + 0.5f));
    if (!ok) {
        e->k = -1;
        return 0;
    }
    if (flash)
        qd_scale(0.5f, 0.5f);
    qd_translate(-e->x, -e->y);
    qd_translate(ap_posex(k), AP_FY);
    qd_scale(AP_S * 0.5f, AP_S * 0.5f);
    qd_path_begin();
    ap_path_part(k, c, p0, p1);
    if (flash) {
        qd_path_stroke(AP_CREAM, lw * 1.1f);
    } else {
        for (g = AP_G0; g < 3; g++) {
            qd_save();
            qd_alpha(AP_GA[g]);
            qd_path_stroke_keep(AP_COL[c], lw * AP_GW[g]);
            qd_restore();
        }
        qd_path_begin();
    }
    qd_layer_end();
    e->done += p1 - p0;
    return 1;
}
/* pose k ready now (built there and then if not): its entry, -1 none (no memory) */
static int ap_ready(int k)
{
    const int i = ap_entry(k);
    if (i < 0)
        return -1;
    while (ap_cache[i].k == k && !AP_READY(&ap_cache[i]))
        ap_build_chunk(i);
    if (ap_cache[i].k != k)
        return -1;
    ap_cache[i].used = ++ap_use;
    return i;
}
/* pose k coming: one chunk of its build (if it is not ready); 1 done (0: it was ready, or no room) */
static int ap_prepare(int k)
{
    const int i = k >= 0 ? ap_entry(k) : -1;
    return i >= 0 && !AP_READY(&ap_cache[i]) && ap_build_chunk(i);
}

void ui_ape_forget(void)                                /* (the renders' measures: from cold) */
{
    int i;
    for (i = 0; i < AP_NC; i++)
        ap_cache[i].k = -1, ap_cache[i].done = 0, ap_cache[i].used = 0u;
}

void ui_ape_prewarm(int ext)                            /* SHIFT held: the first poses on their way, two parts a frame:
                                                         * the point, the step, the flurry's headstand */
{
    static const int8_t K[3] = {0, 1, AP_FLURRY};
    int parts = 2, j = 0;
    ap_keep[0] = ext ? 8 : 0, ap_keep[1] = ext ? -1 : 1;
    while (parts > 0 && j < (ext ? 1 : 3)) {
        if (ap_prepare(ext ? 8 : K[j]))
            parts--;
        else
            j++;
    }
}

typedef struct { float dx, lift, sx, sy, rot, alpha, flash; int mid; } ap_pose_o;
static void ap_place(int i, const ap_pose_o *o)        /* entry i's layers with the transform o */
{
    const int k = ap_cache[i].k;
    const ap_box_t b = ap_posebox(k, o->dx);
    const float ax = b.cx, ay = o->mid ? b.cy : AP_FY;
    const ap_cache_t *e = &ap_cache[i];
    qd_save();
    qd_alpha(qd_get_alpha() * o->alpha);
    qd_translate(ax, ay - o->lift);
    if (o->rot != 0.f)
        qd_rotate(o->rot);
    if (o->sx != 1.f || o->sy != 1.f)
        qd_scale(o->sx, o->sy);
    qd_translate(-ax, -ay);
    qd_layer_draw(2 * i, e->x + o->dx, e->y, e->w, e->h);
    if (o->flash > 0.f) {                               /* the snap's flash: the lines in cream, fading */
        qd_alpha(qd_get_alpha() * o->flash * 0.7f);
        qd_layer_draw(2 * i + 1, e->x + o->dx, e->y, e->w, e->h);
    }
    qd_restore();
}
static void ap_pose(int k, const ap_pose_o *o)
{
    const int i = ap_ready(k);
    if (i >= 0) {
        ap_place(i, o);
        return;
    }
    {   /* (no memory for a layer: drawn directly, every stroke) */
        const ap_box_t b = ap_posebox(k, o->dx);
        const float ax = b.cx, ay = o->mid ? b.cy : AP_FY, lw = 1.55f * 2.f / AP_S;
        int c;
        qd_save();
        qd_alpha(qd_get_alpha() * o->alpha);
        qd_translate(ax, ay - o->lift);
        if (o->rot != 0.f)
            qd_rotate(o->rot);
        qd_scale(o->sx, o->sy);
        qd_translate(-ax, -ay);
        qd_translate(ap_posex(k) + o->dx, AP_FY);
        qd_scale(AP_S * 0.5f, AP_S * 0.5f);
        ap_strokes(k, AP_G0, 2);
        if (o->flash > 0.f) {
            qd_alpha(qd_get_alpha() * o->flash * 0.7f);
            qd_path_begin();
            for (c = 0; c < APE_NCOL; c++)
                ap_path(k, c);
            qd_path_stroke(AP_CREAM, lw * 1.1f);
        }
        qd_restore();
    }
}

#endif

/* ---------------------------------------------------------------- the boombox (the reference's, drawn) */
static void ap_boombox(float x, float y, float w, float h, float pulse)
{
    const float k = w / 68.f, sy = y + h * 0.62f, r = 11.f * k;
    int i;
    {
        const float a[8] = {x + 12.f * k, y, x + 12.f * k, y - 9.f * k, x + w - 12.f * k, y - 9.f * k, x + w - 12.f * k, y};
        const float b[8] = {x + 15.f * k, y, x + 15.f * k, y - 6.f * k, x + w - 15.f * k, y - 6.f * k, x + w - 15.f * k, y};
        ap_line(a, 4, AP_BOX, 1.3f);                    /* the handle */
        ap_line(b, 4, AP_BOX, 1.1f);
    }
    ap_rect(x, y, w, h, 3.f, AP_BOX, 1.4f, UI_BG);   /* (P2.6h, the owner: no side panel, tuner, cassette or keys) */
    for (i = 0; i < 2; i++) {                           /* the speakers: their rings, the cones pumping */
        const float sx = i ? x + w - 13.5f * k : x + 18.5f * k;
        ap_circ(sx, sy, r * (1.f + 0.06f * pulse), AP_SHIRT, 1.4f + 0.5f * pulse);
        ap_circ(sx, sy, r * (0.36f + 0.22f * pulse), AP_FUR, 1.2f + 0.4f * pulse);
    }
}
static void ap_box(float pulse, float shake)
{
    const float w = AP_BW * AP_S, h = AP_BH * AP_S;
    ap_boombox(AP_BX + shake, AP_FY - h - pulse * 1.2f, w, h + pulse * 1.2f, pulse);
}

/* ---------------------------------------------------------------- the head, the BPM */
static void ap_head(int n, qd_rgb col)
{
    const float a = -UI_PI * 0.5f + (float)(n % 12) * AP_TAU / 12.f;
    ui_O(14.f, 12.f, 6.f, col, 1.3f, QD_NONE);
    line2(14.f, 12.f, 14.f + cosf(a) * 5.f, 12.f + sinf(a) * 5.f, col, 1.3f);
    ui_T("TAP", 26.f, 18.f, 12.f, 600, 0.8f, col, QD_LEFT);
}
static void ap_bpm(int v, qd_rgb col, float pop, qd_rgb lab)
{
    char s[12];
    qd_save();
    qd_translate(6.f, 64.f);
    qd_scale(pop, pop);
    ui_T(ui_itoa(s, v), 0.f, 0.f, 44.f, 200, 0.f, col, QD_LEFT);
    qd_restore();
    ui_T("BPM", 8.f, 80.f, 12.f, 600, 0.8f, lab, QD_LEFT);
}
static void ap_floor(void) { line2(8.f, AP_FY + 0.5f, 232.f, AP_FY + 0.5f, UI_G3, 1.f); }

/* ---------------------------------------------------------------- an external clock: tapping does nothing */
static void ap_ext(const ui_turn_t *v)
{
    char s[12];
    const float t = v->t;
    float cx;
    ap_head(0, UI_G2);
    ap_floor();
    ap_bpm(v->value, UI_G1, 1.f, UI_G2);
    cx = 6.f + ui_TW(ui_itoa(s, v->value), 44.f, 200, 0.f) + 20.f;
    ap_circ(cx, 49.f, 11.f, UI_G1, 1.5f);
    ap_line2(cx, 49.f, cx, 42.f, UI_G1, 1.5f);
    ap_line2(cx, 49.f, cx + cosf(t * 0.8f - UI_PI * 0.5f) * 6.f, 49.f + sinf(t * 0.8f - UI_PI * 0.5f) * 6.f, UI_G1, 1.5f);
    ap_dim = 0.45f;                                     /* the boombox and the lounging ape, dimmed, breathing */
    ap_box(0.f, 0.f);
    ap_dim = 1.f;
    ap_keep[0] = 8, ap_keep[1] = -1;
    {
        ap_pose_o o = {0.f, 0.f, 1.f, 1.f + 0.012f * sinf(t * 1.7f), 0.012f * sinf(t * 0.9f), 0.45f, 0.f, 0};
        ap_pose(8, &o);
    }
}

/* ---------------------------------------------------------------- the takeover */
static void ap_burst(const ap_box_t *B, float a0, float seed, int ns, float R)
{
    static const qd_rgb SC[4] = {UI_KSEL, AP_CYAN, AP_FUR, AP_LEAF};
    float u;
    int i;
    if (a0 < 0.f || a0 > 0.5f)
        return;
    u = a0 / 0.5f;
    for (i = 0; i < ns; i++) {
        const float a = seed + (float)i * AP_TAU / (float)ns + ap_hash(seed * 10.f + (float)i) * 0.5f;
        const float r = R * 0.45f + R * ap_easeout(u) * (0.7f + 0.5f * ap_hash((float)i + seed));
        float x = B->cx + cosf(a) * r * 1.1f, y = B->cy + sinf(a) * r * 0.85f;
        x = x < 4.f ? 4.f : x > 236.f ? 236.f : x;
        y = y < 30.f ? 30.f : y > 214.f ? 214.f : y;
        qd_save();
        qd_alpha(qd_get_alpha() * (1.f - u * u));
        ap_sparkle(x, y, 3.6f * (1.f - 0.5f * u), SC[i % 4]);
        qd_restore();
    }
}
static void ap_rings(const ap_box_t *B, float t, int front)
{
    int i;
    for (i = 0; i < 4; i++) {
        const float y = B->y0 + 14.f + (float)i * 14.f, rx = 30.f + (float)i * 4.f, ph = fmodf(t * 9.f + (float)i * 1.3f, AP_TAU);
        const float a0 = front ? ph : ph + UI_PI;
        const qd_rgb col = UI_TRACK_PAL[(i * 2 + (int)floorf(t * 6.f)) % 8];
        int g;
        for (g = 0; g < 3; g++) {
            qd_save();
            qd_alpha(qd_get_alpha() * AP_GA[g]);
            qd_ellipse_arc(B->cx, y, rx, rx * 0.22f, a0, a0 + 1.6f, col, 1.6f * AP_GW[g]);
            qd_restore();
        }
    }
}

void ui_ape_draw(const ui_turn_t *v)
{
    const int n = v->ntotal;
    const float t = v->t, since = v->since;
    const int bpm = n >= 2 ? v->tap_bpm[0] : 0;
    const float beat = bpm ? 60.f / (float)bpm : 0.5f;
    int kind, k, prevk, en, i;
    float age, pulse, lift, dx = 0.f, sx = 1.f, sy = 1.f, rot = 0.f, st;
    int mid = 0, flurry, slow;
    ap_box_t B;
    if (v->ext) {
        ap_ext(v);
        return;
    }
    if (n < 1)
        return;
    /* the event now: the last tap (the first of a count bouncing in), or the finale 2 s on */
    if (since >= AP_TADA) {
        kind = AP_TADAS, k = AP_FINALE, age = since - AP_TADA;
        prevk = ui_ape_pose(n, v->tap_bpm[0]);
    } else {
        kind = n == 1 && !v->tap_cont ? AP_ENTERS : AP_TAP, k = ui_ape_pose(n, v->tap_bpm[0]), age = since;
        prevk = n >= 2 ? ui_ape_pose(n - 1, v->tap_bpm[1]) : -1;
    }
    en = n;
    flurry = kind == AP_TAP && n >= 2 && v->tap_bpm[0] >= 180;
    slow = kind == AP_TAP && n >= 2 && bpm > 0 && bpm <= 70;   /* P1.6g: 70 BPM and under: the slow-motion moonwalk */
    ap_keep[0] = k, ap_keep[1] = kind != AP_ENTERS && age < 0.16f ? prevk : -1;   /* (the poses cached: kept now) */
    ap_head(n, UI_KSEL);
    ap_floor();
    /* the boombox: its speakers pump on each tap (lightly on the beat while the ape grooves); its sound arcs */
    {
        const float tp = kind == AP_ENTERS ? 1.f - ap_clamp(age / 0.3f) : 1.f - ap_clamp(age / 0.3f);
        const float bp = bpm && n >= 2 && kind != AP_TADAS
                             ? powf(0.5f + 0.5f * cosf(AP_TAU * since / beat), 6.f) * 0.45f * ap_ease((since - 0.2f) / 0.2f)
                             : 0.f;
        const float fp = flurry ? 0.5f + 0.5f * sinf(t * 40.f) : 0.f;
        pulse = tp > bp ? tp : bp;
        pulse = pulse > fp ? pulse : fp;
    }
    for (i = 0; i < 3; i++) {
        const float a = age - (float)i * 0.07f;
        if (a < 0.f || a > 0.6f)
            continue;
        qd_save();
        qd_alpha(qd_get_alpha() * (1.f - a / 0.6f) * 0.85f);
        ap_arc(AP_BX + AP_BW * AP_S * 0.5f, AP_FY - AP_BH * AP_S - 8.f, 8.f + 34.f * ap_easeout(a / 0.6f), -UI_PI * 0.85f,
               -UI_PI * 0.15f, UI_KSEL, 1.5f);
        qd_restore();
    }
    ap_box(pulse, flurry ? sinf(t * 50.f) * 1.2f : 0.f);
    if (n >= 2)                                         /* the BPM, from two taps; it pops on each */
        ap_bpm(bpm ? v->value : 0, UI_KSEL, since < 0.15f ? 1.f + 0.08f * (1.f - since / 0.15f) : 1.f, UI_G1);
    /* the groove: the whole drawing on the beat (it ramps in after the snap) */
    lift = 0.f;
    if (slow) {                                         /* P1.6g: gliding back and forth over four beats, a soft step
                                                         * on each, leaning back */
        const float w = ap_ease((age - 0.3f) / 0.4f), ph = age / beat;
        dx = -14.f * (1.f - cosf(AP_TAU * ph / 4.f)) * w;   /* (left, to the boombox, and back) */
        lift = 2.5f * fabsf(sinf(UI_PI * ph)) * w;
        rot = -0.05f * w;
    } else if (kind == AP_TAP && bpm) {
        const float w = ap_ease((age - 0.15f) / 0.15f), ph = age / beat;
        const float c = 0.5f + 0.5f * cosf(AP_TAU * ph), dip = c * c, sway = sinf(UI_PI * ph);
        switch (flurry ? GR_FLIP : AP_GROOVE[k]) {
        case GR_BOB:
            lift = -2.5f * dip * w, sy = 1.f - 0.035f * dip * w, sx = 1.f + 0.015f * dip * w, rot = 0.04f * sway * w;
            break;
        case GR_ROCK: rot = 0.05f * sway * w, lift = 1.5f * (1.f - dip) * w; break;
        case GR_SPIN: rot = 0.2f * sway * w, mid = 1, lift = 2.f * (1.f - dip) * w; break;
        default: {                                      /* the headstand: a paper doll, half a turn a beat */
            const float th = UI_PI * ph * (flurry ? 2.f : 1.f), cs = cosf(th * w), ac = fabsf(cs);
            sx = (cs < 0.f ? -1.f : 1.f) * (ac > 0.25f ? ac : 0.25f);
            lift = 1.5f * (1.f - dip) * w;
            break;
        }
        }
    }
    if (kind == AP_ENTERS) {
        const float u = ap_clamp(age / AP_ENTER);
        dx = 150.f * (1.f - ap_easeout(u));
        lift += 8.f * fabsf(sinf(AP_TAU * u));
    } else {
        const float u = ap_clamp(age / (slow ? AP_HOP * 2.5f : AP_HOP)), s = sinf(UI_PI * u);   /* (slow: in slow
                                                         * motion) */
        lift += (kind == AP_TADAS ? 12.f : 9.f) * s;
        sy *= 1.f + 0.06f * s;
        sx *= 1.f - 0.035f * s;
    }
    /* (P2.6h, the owner: no ghost of the pose it left) */
    B = ap_posebox(k, 0.f);
    if (flurry)
        ap_rings(&B, t, 0);
    {
        ap_pose_o o = {dx, lift, sx, sy, rot, 1.f,
                       kind != AP_ENTERS ? 1.f - ap_clamp(age / (slow ? 0.3f : 0.12f)) : 0.f, mid};
        /* (P2.6d, the owner: the moonwalk's three trail copies gone; it glides alone) */
        ap_pose(k, &o);
    }
    if (flurry)
        ap_rings(&B, t, 1);
    /* the streaks either side (behind it as it bounces in) */
    st = kind == AP_ENTERS ? 1.f - ap_clamp(age / AP_ENTER) : 1.f - ap_clamp(age / 0.2f);
    if (st > 0.f) {
        static const qd_rgb SC[3] = {AP_CYAN, AP_CREAM, AP_FUR};
        qd_save();
        qd_alpha(qd_get_alpha() * st);
        for (i = 0; i < 3; i++) {
            const float y = B.cy - 24.f + (float)i * 22.f;
            if (kind == AP_ENTERS) {
                const float x = B.x1 + dx + 8.f + (float)i * 5.f;
                ap_line2(x, y, x + 24.f, y, SC[i], 1.4f);
            } else {
                const float l = 10.f + 8.f * (1.f - st), xe = B.x1 + 6.f + l;
                ap_line2(B.x0 - 6.f - l, y, B.x0 - 6.f, y, SC[i], 1.3f);
                ap_line2(B.x1 + 6.f, y + 8.f, xe < 238.f ? xe : 238.f, y + 8.f, SC[(i + 1) % 3], 1.3f);
            }
        }
        qd_restore();
    }
    /* the sparkles: a burst out of the ape each tap (a big one for the finale; a shower in the flurry) */
    if (kind != AP_ENTERS)
        ap_burst(&B, age, (float)en * 1.7f + (kind == AP_TADAS ? 3.f : 0.f), kind == AP_TADAS ? 12 : 8,
                 kind == AP_TADAS ? 66.f : 56.f);
    if (flurry)
        for (i = 1; i < 4; i++) {
            const float q = t * 2.5f + (float)i / 3.f, tt = q - floorf(q);
            ap_burst(&B, tt * 0.5f, floorf(q) * 3.1f + (float)i, 5, 60.f);
        }
    /* the tap dots under the floor: the last four bright; they slide off as the count closes */
    {
        const float clr = since > AP_CLEAR0 ? ap_ease((since - AP_CLEAR0) / (AP_TADA - AP_CLEAR0)) : 0.f;
        for (i = v->ntap - 1; i >= 0; i--) {
            const float ag = v->tap_age[i], x = 204.f - ag * 72.f - clr * 220.f;
            const float a = (i < 4 ? 1.f : 0.45f - 0.1f * (float)(i - 4)) * (1.f - clr);
            const float r = ag < 0.25f ? 4.5f + 4.f * (1.f - ag / 0.25f) : 4.5f;
            if (x < 14.f || a <= 0.f)
                continue;
            qd_save();
            qd_alpha(qd_get_alpha() * a);
            ui_O(x, 224.f, r, QD_NONE, 1.f, i < 4 ? UI_KSEL : UI_G1);
            qd_restore();
        }
    }
    /* the pose coming, a chunk of its build a frame: the loop's next; near the count's end the finale; after it the
     * first of a new count */
    {   /* (a part every 15 ms of the clock, however often the screen is drawn; the next pose's BPM guessed from the
         * tempo: 180 and up, the flurry's headstand) */
        static float last_t = -1.f;
        const float dt = last_t < 0.f || t < last_t ? 0.015f : t - last_t > 0.1f ? 0.1f : t - last_t;
        const int guess = n >= 2 ? v->tap_bpm[0] : 0;   /* (after one tap: the step; a flurry from the 2nd tap is
                                                         * rare, its headstand then made at once) */
        const int next = kind == AP_TADAS ? 0 : since < 1.4f ? ui_ape_pose(n + 1, guess) : AP_FINALE;
        const int next2 = n == 1 && kind != AP_TADAS ? AP_FLURRY : -1;   /* (after one tap: the flurry's too) */
        int parts = (int)(dt / 0.015f + 0.5f);
        last_t = t;
        while (parts-- > 0)
            if (!ap_prepare(next) && next2 >= 0)
                ap_prepare(next2);
    }
}
